    private void Install84(){if(!maps.TryGetValue("officina_bassa",out var m))return; if(!m.Enemies.Any(e=>e.Id=="falciante_olmo84"))m.Enemies.Add(new WorldEnemy{Id="falciante_olmo84",Kind="falciante",X=13,Y=3});for(int i=0;i<traps84.Length;i++){var at=traps84[i];string id="trap84_"+i;if(!m.Props.Any(p=>p.Id==id))m.Props.Add(new WorldProp{Id=id,Name="Meccanismo sospetto",X=at.X,Y=at.Y,PaintOnly=true,InteractArea=new double[]{at.X,at.Y,1,1}});}}
