    private void UpdateCompulsion84(float dt){if(game.State.Hero is (HeroId.Roderick or HeroId.Anatema)||game.State.Mind>25){urgeClock84=8;return;}urgeClock84-=dt;if(urgeClock84>0||messageTimer>0)return;urgeClock84=game.State.Mind<=10?12f:24f;Notify(Intrusion84(),5.5f);PlaySound("mind_whisper",-5);curseFlash83=3f;}
    private void DrawWoundDrops84(float w,float h){if(battle==null)return;string k=BattleArt75();for(int i=2;i<6;i++){if(battle.Parts[Parts[i]]>0)continue;Vector2 at= WoundAnchor84(k,i);float x=(at.X-.5f)*w,y=(at.Y-1)*h;for(int j=0;j<5;j++){float t=(tick*.95f+j*.21f+i*.17f)%1;float dx=Mathf.Sin(j*13+i)*t*8;float dy=t*t*48;DrawEllipse(x+dx,y+dy,1.8f-t*.7f,3.2f-t*.8f,new Color(.40f,.055f,.045f,(1-t)*.8f));}DrawEllipse(x,y,4,3,new Color(.32f,.045f,.035f,.65f));}}
    private void Check84(){int n=0;void C(bool ok,string msg){if(!ok)throw new Exception(msg);n++;}foreach(var hero in Enum.GetValues<HeroId>()){game.StartNew(hero,Difficulty.Sopravvivenza);var weapon=game.State.Equipped[GearSlot.Arma];C(game.LoseLimb84("braccioD"),"first arm");C(game.State.Equipped.ContainsKey(GearSlot.Arma),"one arm weapon");C(game.LoseLimb84("braccioS")&&game.NoArms84,"two arms");C(!game.State.Equipped.ContainsKey(GearSlot.Arma)&&!game.Equip(weapon),"no weapon");C(!game.LoseLimb84("braccioS"),"no duplicate");float fast=MoveDelay84();game.LoseLimb84("gambaS");float slow=MoveDelay84();game.LoseLimb84("gambaD");C(fast<slow&&slow<MoveDelay84(),"movement progressive");var restored=GameRules.FromJson(game.ToJson());C(restored.State.LostLimbs84.Count==4&&restored.NoArms84&&!restored.Equip(weapon),"persist");}
    game.StartNew(HeroId.Gladia,Difficulty.Sopravvivenza);ResetEventRules();screen=Screen.World;EnterMap("officina_bassa",9,11);var e=CurrentMap().Enemies.First(e=>e.Kind=="falciante");C(!Blocked("officina_bassa",e.X,e.Y),"enemy reachable");foreach(var t in traps84)C(!Blocked("officina_bassa",t.X,t.Y),"trap walkable");int body=game.State.Body;TriggerTrap84(7,10);C(game.State.Body==body-12&&game.State.Bleeding,"trap damage");TriggerTrap84(7,10);C(game.State.Body==body-12,"once");InspectTrap84(CurrentMap().Props.First(p=>p.Id=="trap84_1"));choices[0].Do();C(TrapDone84(1),"disarm");C(GameRules.FromJson(game.ToJson()).State.StoryFlags.Contains("trap84_0"),"trap persist");StartBattle(e);C(battle!.Armed&&BattleArt75()=="falciante84","sharp enemy");for(int i=0;i<6;i++)C(Art("limb75_falciante84_"+i)!=null,"art "+i);C(Art("anim_falciante84")!=null,"atlas");C(Art("intact82_falciante84")!=null,"full art");GD.Print($"WOUNDS84_OK {n}");GetTree().Quit();}
